// Calculate the converted amount from the exchange-rate reply
const req = $('Webhook — Convert Request').first().json.body;
const api = $input.first().json;
const amount = Number(req.amount);
const from = String(req.from || '').toUpperCase();
const to = String(req.to || '').toUpperCase();

if (api.result !== 'success') {
  return [{ json: { ok: false, error: `Unknown currency: ${from}` } }];
}
if (!amount || amount <= 0) {
  return [{ json: { ok: false, error: 'Amount must be a number above 0' } }];
}
const rate = api.rates[to];
if (!rate) {
  return [{ json: { ok: false, error: `Unknown currency: ${to}` } }];
}
const converted = Math.round(amount * rate * 100) / 100;
return [{ json: { ok: true, result: `${amount} ${from} = ${converted} ${to}`, rate, rate_date: api.time_last_update_utc } }];
